class Solution {
  public int[] anagramMappings(int[] nums1, int[] nums2) {
    Map<Integer, Integer> position = new HashMap<>();
    for (int i = 0; i < nums2.length; i++) position.put(nums2[i], i);
    int[] ans = new int[nums1.length];
    for (int i = 0; i < ans.length; i++) ans[i] = position.get(nums1[i]);
    return ans;
  }
}
